protected void printInteger(SQLIntegerExpr x, boolean parameterized) {
    long val = x.getNumber().longValue();

    if (val == 1) {
        if (JdbcConstants.ORACLE.equals(dbType)) {
            SQLObject parent = x.getParent();
            if (parent instanceof SQLBinaryOpExpr) {
                SQLBinaryOpExpr binaryOpExpr = (SQLBinaryOpExpr) parent;
                SQLExpr left = binaryOpExpr.getLeft();
                SQLBinaryOperator op = binaryOpExpr.getOperator();
                if (left instanceof SQLIdentifierExpr
                        && op == SQLBinaryOperator.Equality) {
                    String name = ((SQLIdentifierExpr) left).getName();
                    if ("rownum".equals(name)) {
                        print(1);
                        return;
                    }
                }
            }
        }
    }
    if (parameterized) {
        print('?');
        incrementReplaceCunt();

        if(this.parameters != null){
            ExportParameterVisitorUtils.exportParameter(this.parameters, x);
        }
        return;
    }

    // Correct handling of large unsigned long values
    if (val < 0) {
        // Handle the case of large unsigned value represented as a negative value
        BigInteger unsignedVal = BigInteger.valueOf(x.getNumber().longValue()).and(new BigInteger("FFFFFFFFFFFFFFFF", 16));
        print(unsignedVal.toString());
    } else {
        print(val);
    }
}

